function mod97(s) {
  let r = 0;
  for (const ch of s) {
    const v = /[A-Z]/.test(ch) ? String(ch.charCodeAt(0) - 55) : ch;
    for (const d of v) r = (r * 10 + Number(d)) % 97;
  }
  return r;
}
function make(bank, acct) {
  const bban = bank + "0" + acct;
  const chk = 98 - mod97(bban + "TR00");
  return "TR" + String(chk).padStart(2, "0") + bban;
}
