              <div style={styles.skeletonText}>
                <Skeleton lines={2} />
              </div>
            </div>
          ))}
        </div>
      </Card>
    );
  }

  if (state.status === "error") {
    return (
      <Alert
        tone="danger"
        title="We could not load your recipients"
