1	/**
2	 * TransferScreen: send Turkish lira to a saved or new recipient.
3	 *
4	 * Flow: Recipient, Amount, Review, Confirm (SMS one-time code), then a receipt.
5	 *
6	 * Expects the app root to load the Leeward styles and set the theme:
7	 *   import "@leeward/react/fonts.css";
8	 *   import "@leeward/react/styles.css";
9	 *   <div data-brand="leeward" data-theme="light">...</div>
10	 *
11	 * Mock data:
12	 *   - The one-time code is 123456. Any other code counts as a wrong try (3 tries per code).
13	 *   - A valid new IBAN to try: TR33 0006 1005 1978 6457 8413 26.
14	 *   - Transfers between Leeward accounts are free. Other banks cost ₺6,50.
15	 */
16	import {
17	  type FormEvent,
18	  type ReactNode,
19	  type CSSProperties,
20	  useCallback,
21	  useEffect,
22	  useId,
23	  useMemo,
24	  useRef,
25	  useState,
26	  useSyncExternalStore,
27	} from "react";
28	import {
29	  Alert,
30	  AmountDisplay,
31	  AmountInput,
32	  Avatar,
33	  Button,
34	  Card,
35	  Checkbox,
36	  Divider,
37	  EmptyState,
38	  Heading,
39	  Icon,
40	  IconButton,
41	  List,
42	  ListItem,
43	  OTPInput,
44	  SegmentedControl,
45	  Skeleton,
46	  Stepper,
47	  Text,
48	  TextField,
49	  formatIban,
50	  maskIban,
51	} from "@leeward/react";
52	
53	/* -------------------------------------------------------------------------- */
54	/* Types                                                                      */
55	/* -------------------------------------------------------------------------- */
56	
57	type Recipient = {
58	  id: string;
59	  name: string;
60	  /** Normalized: uppercase, no spaces. */
61	  iban: string;
62	  bankName: string;
63	  isLeeward: boolean;
64	};
65	
66	type Account = {
67	  name: string;
68	  iban: string;
69	  /** Available balance in kuruş, so money math stays in integers. */
70	  balanceKurus: number;
71	  /** Masked phone number the SMS code goes to. */
72	  maskedPhone: string;
73	};
74	
75	type Step = "recipient" | "amount" | "review" | "verify" | "done";
76	
77	type RecipientsState =
78	  | { status: "loading" }
79	  | { status: "error" }
80	  | { status: "ready"; recipients: Recipient[] };
81	
82	type CodeSession = { transferId: string; resendAvailableAt: number };
83	
84	type ConfirmResult =
85	  | { status: "sent"; reference: string; sentAt: number }
86	  | { status: "wrong-code"; attemptsLeft: number }
87	  | { status: "locked" }
88	  | { status: "expired" };
89	
90	export type TransferScreenProps = {
91	  /** Called when the person leaves the flow, from the close button or the receipt. */
92	  onClose?: () => void;
93	};
94	
95	/* -------------------------------------------------------------------------- */
96	/* Constants and mock data                                                    */
97	/* -------------------------------------------------------------------------- */
98	
99	const CURRENCY = "TRY";
100	const LOCALE = "tr-TR";
101	const IBAN_LENGTH_TR = 26;
102	const LEEWARD_BANK_CODE = "00829";
103	const OTHER_BANK_FEE_KURUS = 650;
104	const MIN_AMOUNT_KURUS = 100;
105	const DESCRIPTION_MAX_LENGTH = 140;
106	const CODE_LENGTH = 6;
107	const CODE_TTL_MS = 3 * 60 * 1000;
108	const RESEND_COOLDOWN_MS = 30 * 1000;
109	const MAX_CODE_ATTEMPTS = 3;
110	
111	const STEP_NAMES = ["Recipient", "Amount", "Review", "Confirm"];
112	const STEP_INDEX: Record<Exclude<Step, "done">, number> = {
113	  recipient: 0,
114	  amount: 1,
115	  review: 2,
116	  verify: 3,
117	};
118	
119	/** Bank codes are digits 5 to 9 of a Turkish IBAN. */
120	const BANKS_BY_CODE: Record<string, string> = {
121	  [LEEWARD_BANK_CODE]: "Leeward",
122	  "00010": "Ziraat Bankası",
123	  "00046": "Akbank",
124	  "00062": "Garanti BBVA",
125	  "00064": "Türkiye İş Bankası",
126	  "00067": "Yapı Kredi",
127	};
128	
129	const MOCK_ACCOUNT: Account = {
130	  name: "Main account",
131	  iban: "TR120082900000000045712388",
132	  balanceKurus: 2_458_035,
133	  maskedPhone: "•••• 4821",
134	};
135	
136	const MOCK_RECIPIENTS: Recipient[] = [
137	  { id: "r1", name: "Deniz Yılmaz", iban: "TR720082900000000011904577", bankName: "Leeward", isLeeward: true },
138	  { id: "r2", name: "Ayşe Kaya", iban: "TR330006200001298745630012", bankName: "Garanti BBVA", isLeeward: false },
139	  { id: "r3", name: "Mehmet Demir", iban: "TR670006400000883412075566", bankName: "Türkiye İş Bankası", isLeeward: false },
140	  { id: "r4", name: "Elif Şahin", iban: "TR130004600007710345982201", bankName: "Akbank", isLeeward: false },
141	  { id: "r5", name: "Can Öztürk", iban: "TR740006700000569021347789", bankName: "Yapı Kredi", isLeeward: false },
142	];
143	
144	const MOCK_VALID_CODE = "123456";
145	
146	/* -------------------------------------------------------------------------- */
147	/* Mock API                                                                   */
148	/* -------------------------------------------------------------------------- */
149	
150	function wait(ms: number, signal?: AbortSignal): Promise<void> {
151	  return new Promise((resolve, reject) => {
152	    if (signal?.aborted) {
153	      reject(new DOMException("Aborted", "AbortError"));
154	      return;
155	    }
156	    const timer = setTimeout(resolve, ms);
157	    signal?.addEventListener(
158	      "abort",
159	      () => {
160	        clearTimeout(timer);
161	        reject(new DOMException("Aborted", "AbortError"));
162	      },
163	      { once: true },
164	    );
165	  });
166	}
167	
168	function isAbortError(error: unknown): boolean {
169	  return error instanceof DOMException && error.name === "AbortError";
170	}
171	
172	type MockCodeSession = {
173	  code: string;
174	  expiresAt: number;
175	  attemptsLeft: number;
176	  result?: ConfirmResult;
177	};
178	
179	const mockSessions = new Map<string, MockCodeSession>();
180	
181	const mockApi = {
182	  async fetchRecipients(signal?: AbortSignal): Promise<Recipient[]> {
183	    await wait(700, signal);
184	    return MOCK_RECIPIENTS.map((recipient) => ({ ...recipient }));
185	  },
186	
187	  /** Sends a new SMS code for a transfer. A new code replaces the old one. */
188	  async requestCode(transferId: string, signal?: AbortSignal): Promise<void> {
189	    await wait(600, signal);
190	    const existing = mockSessions.get(transferId);
191	    if (existing?.result?.status === "sent") return;
192	    mockSessions.set(transferId, {
193	      code: MOCK_VALID_CODE,
194	      expiresAt: Date.now() + CODE_TTL_MS,
195	      attemptsLeft: MAX_CODE_ATTEMPTS,
196	    });
197	  },
198	
199	  /**
200	   * Checks the code and sends the money. `transferId` is the idempotency key:
201	   * repeating a call for a sent transfer returns the same result and never sends twice.
202	   */
203	  async confirmTransfer(transferId: string, code: string, signal?: AbortSignal): Promise<ConfirmResult> {
204	    await wait(900, signal);
205	    const session = mockSessions.get(transferId);
206	    if (!session) return { status: "expired" };
207	    if (session.result?.status === "sent") return session.result;
208	    if (session.attemptsLeft <= 0) return { status: "locked" };
209	    if (Date.now() > session.expiresAt) return { status: "expired" };
210	
211	    if (code !== session.code) {
212	      session.attemptsLeft -= 1;
213	      return session.attemptsLeft > 0 ? { status: "wrong-code", attemptsLeft: session.attemptsLeft } : { status: "locked" };
214	    }
215	
216	    const result: ConfirmResult = {
217	      status: "sent",
218	      reference: `LW${transferId.replace(/-/g, "").slice(0, 10).toUpperCase()}`,
219	      sentAt: Date.now(),
220	    };
221	    session.result = result;
222	    return result;
223	  },
224	};
