226	/* -------------------------------------------------------------------------- */
227	/* Money and IBAN helpers                                                     */
228	/* -------------------------------------------------------------------------- */
229	
230	const toKurus = (lira: number): number => Math.round(lira * 100);
231	const toLira = (kurus: number): number => kurus / 100;
232	
233	function feeKurusFor(recipient: Recipient): number {
234	  return recipient.isLeeward ? 0 : OTHER_BANK_FEE_KURUS;
235	}
236	
237	function normalizeIban(value: string): string {
238	  return value.replace(/\s+/g, "").toUpperCase();
239	}
240	
241	/** ISO 13616 mod 97 check: move the first four characters to the end, letters become 10 to 35. */
242	function hasValidChecksum(iban: string): boolean {
243	  const rearranged = iban.slice(4) + iban.slice(0, 4);
244	  let remainder = 0;
245	  for (const char of rearranged) {
246	    const digits = /[A-Z]/.test(char) ? String(char.charCodeAt(0) - 55) : char;
247	    for (const digit of digits) {
248	      remainder = (remainder * 10 + Number(digit)) % 97;
249	    }
250	  }
251	  return remainder === 1;
252	}
253	
254	function validateIban(raw: string, ownIban: string): string | undefined {
255	  const iban = normalizeIban(raw);
256	  if (iban.length === 0) return "Enter the IBAN of the person you are paying.";
257	  if (!iban.startsWith("TR")) return "Turkish IBANs start with TR. Check it and try again.";
258	  if (!/^TR\d+$/.test(iban)) return "After TR, an IBAN has only numbers. Check it and try again.";
259	  if (iban.length < IBAN_LENGTH_TR) return "This IBAN is too short. Check it and try again.";
260	  if (iban.length > IBAN_LENGTH_TR) return "This IBAN is too long. Check it and try again.";
261	  if (!hasValidChecksum(iban)) return "This IBAN has a typo somewhere. Check each number and try again.";
262	  if (iban === ownIban) return "This is your own account. Enter the IBAN of the person you are paying.";
263	  return undefined;
264	}
265	
266	function validateName(raw: string): string | undefined {
267	  const name = raw.trim().replace(/\s+/g, " ");
268	  if (name.length === 0) return "Enter the full name of the person you are paying.";
269	  if (!/^[\p{L}][\p{L}' .-]*$/u.test(name)) return "Use letters only. Check the name and try again.";
270	  if (name.split(" ").length < 2) return "Enter their first and last name, as their bank has it.";
271	  return undefined;
272	}
273	
274	function bankFromIban(iban: string): { bankName: string; isLeeward: boolean } {
275	  const code = iban.slice(4, 9);
276	  return { bankName: BANKS_BY_CODE[code] ?? "Another bank", isLeeward: code === LEEWARD_BANK_CODE };
277	}
278	
279	function createTransferId(): string {
280	  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") return crypto.randomUUID();
281	  return `t-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
282	}
283	
284	function arrivalCopy(recipient: Recipient): string {
285	  return recipient.isLeeward ? "In seconds" : "In a few minutes";
286	}
287	
288	/* -------------------------------------------------------------------------- */
289	/* Hooks                                                                      */
290	/* -------------------------------------------------------------------------- */
291	
292	function useMediaQuery(query: string): boolean {
293	  const subscribe = useCallback(
294	    (onChange: () => void) => {
295	      const media = window.matchMedia(query);
296	      media.addEventListener("change", onChange);
297	      return () => media.removeEventListener("change", onChange);
298	    },
299	    [query],
300	  );
301	  return useSyncExternalStore(
302	    subscribe,
303	    () => window.matchMedia(query).matches,
304	    () => false,
305	  );
306	}
307	
308	/** Current time, ticking every second while `active`. */
309	function useNow(active: boolean): number {
310	  const [now, setNow] = useState(() => Date.now());
311	  useEffect(() => {
312	    if (!active) return;
313	    setNow(Date.now());
314	    const timer = setInterval(() => setNow(Date.now()), 1000);
315	    return () => clearInterval(timer);
316	  }, [active]);
317	  return now;
318	}
319	
320	/** One AbortController per component, aborted on unmount. */
321	function useAbortSignal(): () => AbortSignal {
322	  const controllers = useRef(new Set<AbortController>());
323	  useEffect(() => {
324	    const active = controllers.current;
325	    return () => {
326	      active.forEach((controller) => controller.abort());
327	      active.clear();
328	    };
329	  }, []);
330	  return useCallback(() => {
331	    const controller = new AbortController();
332	    controllers.current.add(controller);
333	    return controller.signal;
334	  }, []);
335	}
336	
337	/* -------------------------------------------------------------------------- */
338	/* Layout                                                                     */
339	/* -------------------------------------------------------------------------- */
340	
341	const styles = {
342	  page: {
343	    minHeight: "100%",
344	    background: "var(--lw-fill-surface-canvas)",
345	    color: "var(--lw-text-default)",
346	  },
347	  column: {
348	    display: "flex",
