375	  skeletonRow: { display: "flex", alignItems: "center", gap: "var(--lw-space-sm)", padding: "var(--lw-space-sm) var(--lw-space-md)" },
376	  skeletonText: { flex: 1 },
377	} satisfies Record<string, CSSProperties>;
378	
379	const STEP_HEADING_ID = "transfer-step-heading";
380	
381	/* -------------------------------------------------------------------------- */
382	/* Shared pieces                                                              */
383	/* -------------------------------------------------------------------------- */
384	
385	function StepHeading({ children, description }: { children: ReactNode; description?: ReactNode }) {
386	  return (
387	    <div style={styles.group}>
388	      <Heading level={2} size="h3" id={STEP_HEADING_ID} tabIndex={-1}>
389	        {children}
390	      </Heading>
391	      {description ? <Text tone="secondary">{description}</Text> : null}
392	    </div>
