395	
396	function SummaryRow({ label, children, emphasis = false }: { label: string; children: ReactNode; emphasis?: boolean }) {
397	  return (
398	    <div style={styles.summaryRow}>
399	      <Text as="dt" variant={emphasis ? "label-lg" : "body-md"} tone={emphasis ? "primary" : "secondary"}>
400	        {label}
401	      </Text>
402	      <Text as="dd" variant={emphasis ? "label-lg" : "body-md"} style={styles.summaryValue}>
403	        {children}
404	      </Text>
405	    </div>
406	  );
407	}
408	
409	function Money({ kurus, direction = "neutral", size = "md" }: { kurus: number; direction?: "outgoing" | "neutral"; size?: "sm" | "md" | "lg" }) {
410	  return <AmountDisplay value={toLira(kurus)} currency={CURRENCY} locale={LOCALE} direction={direction} size={size} />;
411	}
412	
413	function FeeValue({ recipient }: { recipient: Recipient }) {
414	  const feeKurus = feeKurusFor(recipient);
415	  return (
416	    <>
417	      <Money kurus={feeKurus} />
418	      {feeKurus === 0 ? (
419	        <Text as="span" variant="caption" tone="secondary" style={{ display: "block" }}>
420	          Free between Leeward accounts
421	        </Text>
422	      ) : null}
423	    </>
424	  );
425	}
426	
427	/* -------------------------------------------------------------------------- */
428	/* Step 1: Recipient                                                          */
429	/* -------------------------------------------------------------------------- */
430	
431	type RecipientMode = "saved" | "new";
432	
433	type NewRecipientDraft = { name: string; iban: string; save: boolean };
434	
435	function RecipientStep({
436	  recipientsState,
437	  onRetry,
438	  onChoose,
439	  account,
440	  draft,
441	  onDraftChange,
442	}: {
443	  recipientsState: RecipientsState;
444	  onRetry: () => void;
445	  onChoose: (recipient: Recipient, saveAsNew: boolean) => void;
446	  account: Account;
447	  draft: NewRecipientDraft;
448	  onDraftChange: (draft: NewRecipientDraft) => void;
449	}) {
450	  const [mode, setMode] = useState<RecipientMode>("saved");
451	  const [query, setQuery] = useState("");
452	  const [touched, setTouched] = useState({ name: false, iban: false });
453	  const [submitted, setSubmitted] = useState(false);
454	  const fieldId = useId();
455	  const nameId = `${fieldId}-name`;
456	  const ibanId = `${fieldId}-iban`;
457	
458	  const nameError = submitted || touched.name ? validateName(draft.name) : undefined;
459	  const ibanError = submitted || touched.iban ? validateIban(draft.iban, account.iban) : undefined;
460	
461	  const filtered = useMemo(() => {
462	    if (recipientsState.status !== "ready") return [];
463	    const needle = query.trim().toLocaleLowerCase(LOCALE);
464	    if (!needle) return recipientsState.recipients;
465	    const ibanNeedle = normalizeIban(needle);
466	    return recipientsState.recipients.filter(
467	      (recipient) =>
468	        recipient.name.toLocaleLowerCase(LOCALE).includes(needle) ||
469	        recipient.bankName.toLocaleLowerCase(LOCALE).includes(needle) ||
470	        (ibanNeedle.length >= 4 && recipient.iban.includes(ibanNeedle)),
471	    );
472	  }, [recipientsState, query]);
473	
474	  function handleNewSubmit(event: FormEvent<HTMLFormElement>) {
475	    event.preventDefault();
476	    setSubmitted(true);
477	    const nextNameError = validateName(draft.name);
478	    const nextIbanError = validateIban(draft.iban, account.iban);
479	    if (nextNameError || nextIbanError) {
480	      document.getElementById(nextNameError ? nameId : ibanId)?.focus();
481	      return;
482	    }
