882	function formatCountdown(ms: number): string {
883	  const totalSeconds = Math.max(0, Math.ceil(ms / 1000));
884	  const minutes = Math.floor(totalSeconds / 60);
885	  const seconds = totalSeconds % 60;
886	  return `${minutes}:${String(seconds).padStart(2, "0")}`;
887	}
888	
889	function VerifyStep({
890	  recipient,
891	  account,
892	  totalKurus,
893	  session,
894	  onResend,
895	  resending,
896	  resendFailed,
897	  onConfirm,
898	}: {
899	  recipient: Recipient;
900	  account: Account;
901	  totalKurus: number;
902	  session: CodeSession;
903	  onResend: () => Promise<boolean>;
904	  resending: boolean;
905	  resendFailed: boolean;
906	  onConfirm: (code: string) => Promise<ConfirmResult | "failed">;
907	}) {
908	  const [code, setCode] = useState("");
909	  const [error, setError] = useState<string | undefined>();
910	  const [locked, setLocked] = useState(false);
911	  const [submitting, setSubmitting] = useState(false);
912	  const [sendFailed, setSendFailed] = useState(false);
913	  const submittingRef = useRef(false);
914	  const otpId = useId();
915	
916	  // Tick only while the resend cooldown runs.
917	  const now = useNow(session.resendAvailableAt > Date.now());
918	  const resendInMs = session.resendAvailableAt - now;
919	
920	  async function submit(value: string) {
921	    if (submittingRef.current || locked) return;
922	    if (value.length < CODE_LENGTH) {
923	      setError(`Enter all ${CODE_LENGTH} digits of the code.`);
924	      document.getElementById(otpId)?.focus();
925	      return;
926	    }
927	    submittingRef.current = true;
928	    setSubmitting(true);
929	    setError(undefined);
930	    setSendFailed(false);
931	    try {
932	      const result = await onConfirm(value);
933	      if (result === "failed") {
934	        setSendFailed(true);
935	        return;
936	      }
937	      switch (result.status) {
938	        case "sent":
939	          return;
940	        case "wrong-code":
941	          setError(
942	            `This code does not match. Check the SMS and try again. ${result.attemptsLeft} ${
943	              result.attemptsLeft === 1 ? "try" : "tries"
944	            } left.`,
945	          );
946	          return;
947	        case "expired":
948	          setError("This code has expired. Send a new code and try again.");
949	          return;
950	        case "locked":
951	          setLocked(true);
952	          return;
953	      }
954	    } finally {
955	      submittingRef.current = false;
956	      setSubmitting(false);
957	    }
958	  }
959	
960	  async function resend() {
961	    const ok = await onResend();
962	    if (ok) {
963	      setCode("");
964	      setError(undefined);
965	      setLocked(false);
966	      setSendFailed(false);
967	      document.getElementById(otpId)?.focus();
968	    }
969	  }
970	
971	  return (
972	    <section style={styles.section} aria-labelledby={STEP_HEADING_ID}>
973	      <StepHeading
974	        description={
975	          <>
976	            You are sending <Money kurus={totalKurus} size="sm" /> to {recipient.name}, fee included.
977	          </>
978	        }
979	      >
980	        Enter your code
981	      </StepHeading>
982	
983	      <form
984	        noValidate
985	        style={styles.section}
986	        onSubmit={(event) => {
987	          event.preventDefault();
988	          void submit(code);
989	        }}
990	      >
991	        <OTPInput
992	          id={otpId}
993	          label="Verification code"
994	          length={CODE_LENGTH}
995	          locale={LOCALE}
996	          hint={`We sent a code to ${account.maskedPhone}. It expires in 3 minutes.`}
997	          value={code}
998	          onChange={(value) => {
999	            setCode(value);
1000	            if (error) setError(undefined);
1001	          }}
1002	          onComplete={(value) => void submit(value)}
1003	          disabled={locked || submitting}
1004	          autoFocus
1005	          {...(error ? { error } : {})}
1006	        />
1007	
1008	        {locked ? (
1009	          <Alert tone="danger" live="alert" title="Too many wrong codes">
1010	            Nothing left your account. Send a new code to try again.
1011	          </Alert>
1012	        ) : null}
1013	
1014	        {sendFailed ? (
1015	          <Alert tone="danger" live="alert" title="We could not send your money">
1016	            Nothing left your account. Check your connection and try again.
1017	          </Alert>
1018	        ) : null}
1019	
1020	        {resendFailed ? (
1021	          <Alert tone="danger" title="We could not send a new code">
1022	            Check your connection and try again.
1023	          </Alert>
1024	        ) : null}
1025	
1026	        <div style={styles.actions}>
1027	          <Button type="submit" variant="primary" size="xl" fullWidth iconStart="send" loading={submitting} disabled={locked}>
1028	            Confirm and send
1029	          </Button>
1030	          <Button
1031	            type="button"
1032	            variant="ghost"
1033	            fullWidth
1034	            iconStart="refresh"
1035	            loading={resending}
1036	            disabled={submitting || resendInMs > 0}
1037	            onClick={() => void resend()}
1038	          >
1039	            {resendInMs > 0 ? `Send a new code in ${formatCountdown(resendInMs)}` : "Send a new code"}
1040	          </Button>
1041	        </div>
1042	      </form>
1043	    </section>
1044	  );
1045	}
