1148	    try {
1149	      const recipients = await mockApi.fetchRecipients(nextSignal());
1150	      setRecipientsState({ status: "ready", recipients });
1151	    } catch (error) {
1152	      if (!isAbortError(error)) setRecipientsState({ status: "error" });
1153	    }
1154	  }, [nextSignal]);
1155	
1156	  useEffect(() => {
1157	    void loadRecipients();
1158	  }, [loadRecipients]);
1159	
1160	  // Move focus to the new step heading so keyboard and screen reader users start at the top.
1161	  // The verify step focuses the code field instead.
1162	  const isFirstRender = useRef(true);
1163	  useEffect(() => {
1164	    if (isFirstRender.current) {
1165	      isFirstRender.current = false;
1166	      return;
1167	    }
1168	    if (step !== "verify") document.getElementById(STEP_HEADING_ID)?.focus();
1169	  }, [step]);
1170	
