1172	  const feeKurus = recipient ? feeKurusFor(recipient) : 0;
1173	  const totalKurus = amountKurus + feeKurus;
1174	
1175	  async function requestCode(transferId: string): Promise<boolean> {
1176	    try {
1177	      await mockApi.requestCode(transferId, nextSignal());
