1179	      return true;
1180	    } catch (error) {
1181	      if (isAbortError(error)) return false;
1182	      throw error;
1183	    }
1184	  }
1185	
1186	  async function handleReviewConfirm() {
1187	    if (requestingCode) return;
1188	    setRequestingCode(true);
1189	    setRequestFailed(false);
1190	    try {
1191	      // A new transfer id per review keeps a stale code from confirming changed details.
1192	      if (await requestCode(createTransferId())) setStep("verify");
1193	    } catch {
1194	      setRequestFailed(true);
1195	    } finally {
1196	      setRequestingCode(false);
1197	    }
1198	  }
1199	
1200	  const [resending, setResending] = useState(false);
1201	  const [resendFailed, setResendFailed] = useState(false);
1202	
1203	  async function handleResend(): Promise<boolean> {
1204	    if (!session || resending) return false;
1205	    setResending(true);
1206	    setResendFailed(false);
1207	    try {
1208	      return await requestCode(session.transferId);
1209	    } catch {
1210	      setResendFailed(true);
1211	      return false;
1212	    } finally {
1213	      setResending(false);
1214	    }
1215	  }
1216	
1217	  async function handleConfirm(code: string): Promise<ConfirmResult | "failed"> {
1218	    if (!session || !recipient) return "failed";
1219	    try {
1220	      const result = await mockApi.confirmTransfer(session.transferId, code, nextSignal());
1221	      if (result.status === "sent") {
1222	        const saved = saveRecipient && recipient.id.startsWith("new-");
1223	        if (saved && recipientsState.status === "ready") {
1224	          setRecipientsState({
1225	            status: "ready",
1226	            recipients: [{ ...recipient, id: `saved-${recipient.iban}` }, ...recipientsState.recipients],
1227	          });
1228	        }
1229	        setAccount((current) => ({ ...current, balanceKurus: current.balanceKurus - totalKurus }));
1230	        setReceipt({ reference: result.reference, sentAt: result.sentAt, saved });
1231	        setSession(null);
1232	        setStep("done");
1233	      }
1234	      return result;
1235	    } catch {
1236	      // Aborts and network failures both mean nothing was sent.
1237	      return "failed";
1238	    }
1239	  }
1240	
1241	  function goBack() {
1242	    switch (step) {
1243	      case "amount":
1244	        setStep("recipient");
1245	        break;
1246	      case "review":
1247	        setRequestFailed(false);
1248	        setStep("amount");
1249	        break;
1250	      case "verify":
1251	        // Leaving the code step voids the code: details may change before the next try.
1252	        setSession(null);
1253	        setResendFailed(false);
1254	        setStep("review");
1255	        break;
1256	      default:
1257	        break;
1258	    }
1259	  }
1260	
1261	  function startOver() {
1262	    setRecipient(null);
1263	    setSaveRecipient(false);
1264	    setDraft(EMPTY_DRAFT);
1265	    setAmount(null);
1266	    setDescription("");
1267	    setReceipt(null);
1268	    setStep("recipient");
1269	  }
1270	
1271	  const canGoBack = step === "amount" || step === "review" || step === "verify";
1272	
1273	  return (
1274	    <main style={styles.page}>
1275	      <div style={styles.column}>
1276	        <header style={styles.header}>
1277	          {canGoBack ? (
1278	            <Button variant="ghost" iconStart="arrow-left" onClick={goBack}>
1279	              Back
1280	            </Button>
1281	          ) : (
1282	            <span />
1283	          )}
1284	          {onClose && step !== "done" ? <IconButton icon="close" label="Cancel transfer" variant="ghost" onClick={onClose} /> : null}
1285	        </header>
1286	
1287	        <Heading level={1} size="title-md">
1288	          Send money
1289	        </Heading>
1290	
1291	        {step !== "done" ? (
1292	          <Stepper
1293	            steps={STEP_NAMES}
1294	            current={STEP_INDEX[step]}
1295	            variant={isWide ? "full" : "compact"}
1296	            label="Transfer progress"
1297	          />
1298	        ) : null}
1299	
1300	        {step === "recipient" ? (
1301	          <RecipientStep
1302	            recipientsState={recipientsState}
1303	            onRetry={() => void loadRecipients()}
1304	            account={account}
1305	            draft={draft}
1306	            onDraftChange={setDraft}
