type RecipientMode = "saved" | "new";
type NewRecipientDraft = { name: string; iban: string; save: boolean };

function RecipientStep({ recipientsState, onRetry, onChoose, account, draft, onDraftChange }: {
  recipientsState: RecipientsState; onRetry: () => void; onChoose: (recipient: Recipient, saveAsNew: boolean) => void;
  account: Account; draft: NewRecipientDraft; onDraftChange: (draft: NewRecipientDraft) => void;
}) {
  const [mode, setMode] = useState<RecipientMode>(() => (draft.name || draft.iban ? "new" : "saved"));
  const [query, setQuery] = useState("");
  const [touched, setTouched] = useState({ name: false, iban: false });
  const [submitted, setSubmitted] = useState(false);
  const fieldId = useId();
  const nameId = `${fieldId}-name`;
  const ibanId = `${fieldId}-iban`;
  const nameError = submitted || touched.name ? validateName(draft.name) : undefined;
  const ibanError = submitted || touched.iban ? validateIban(draft.iban, account.iban) : undefined;

  const filtered = useMemo(() => {
    if (recipientsState.status !== "ready") return [];
    const needle = query.trim().toLocaleLowerCase(LOCALE);
    if (!needle) return recipientsState.recipients;
    const ibanNeedle = normalizeIban(needle);
    return recipientsState.recipients.filter((recipient) =>
      recipient.name.toLocaleLowerCase(LOCALE).includes(needle) ||
      recipient.bankName.toLocaleLowerCase(LOCALE).includes(needle) ||
      (ibanNeedle.length >= 4 && recipient.iban.includes(ibanNeedle)));
  }, [recipientsState, query]);

  function handleNewSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitted(true);
    const nextNameError = validateName(draft.name);
    const nextIbanError = validateIban(draft.iban, account.iban);
    if (nextNameError || nextIbanError) { document.getElementById(nextNameError ? nameId : ibanId)?.focus(); return; }
    const iban = normalizeIban(draft.iban);
    const existing = recipientsState.status === "ready" ? recipientsState.recipients.find((r) => r.iban === iban) : undefined;
    if (existing) { onChoose(existing, false); return; }
    const name = draft.name.trim().replace(/\s+/g, " ");
    onChoose({ id: `new-${iban}`, name, iban, ...bankFromIban(iban) }, draft.save);
  }

  return (
    <section style={styles.section} aria-labelledby={STEP_HEADING_ID}>
      <StepHeading>Who are you paying?</StepHeading>
      <SegmentedControl label="Recipient type" value={mode} onValueChange={(value) => setMode(value as RecipientMode)} fullWidth
        options={[{ value: "saved", label: "Saved" }, { value: "new", label: "New" }]} />
      {mode === "saved" ? (
        <SavedRecipients state={recipientsState} recipients={filtered} query={query} onQueryChange={setQuery} onRetry={onRetry}
          onChoose={(recipient) => onChoose(recipient, false)} onAddNew={() => setMode("new")} />
      ) : (
        <form noValidate onSubmit={handleNewSubmit} style={styles.section}>
          <div style={styles.group}>
            <TextField id={nameId} label="Full name" hint="First and last name, as their bank has it" autoComplete="off" autoCapitalize="words"
              value={draft.name} onChange={(event) => onDraftChange({ ...draft, name: event.target.value })}
              onBlur={() => setTouched((t) => ({ ...t, name: true }))} {...(nameError ? { error: nameError } : {})} />
            <TextField id={ibanId} label="IBAN" hint="26 characters, starts with TR" autoComplete="off" autoCapitalize="characters" spellCheck={false} numeric
              value={draft.iban} onChange={(event) => onDraftChange({ ...draft, iban: event.target.value.toUpperCase() })}
              onBlur={() => { setTouched((t) => ({ ...t, iban: true })); const iban = normalizeIban(draft.iban); if (iban.length === IBAN_LENGTH_TR) onDraftChange({ ...draft, iban: formatIban(iban) }); }}
              {...(ibanError ? { error: ibanError } : {})} />
            <Checkbox label="Save this person as a recipient" checked={draft.save} onCheckedChange={(checked) => onDraftChange({ ...draft, save: checked === true })} />
          </div>
          <Button type="submit" variant="primary" size="lg" fullWidth>Continue</Button>
        </form>
      )}
    </section>
  );
}

function SavedRecipients({ state, recipients, query, onQueryChange, onRetry, onChoose, onAddNew }: {
  state: RecipientsState; recipients: Recipient[]; query: string; onQueryChange: (query: string) => void;
  onRetry: () => void; onChoose: (recipient: Recipient) => void; onAddNew: () => void;
