        action={<Button variant="secondary" iconStart="user-plus" onClick={onAddNew}>Add a new recipient</Button>} />
    );
  }
  return (
    <div style={styles.group}>
      <TextField label="Search recipients" type="search" autoComplete="off" value={query} onChange={(event) => onQueryChange(event.target.value)} />
      {recipients.length === 0 ? (
        <EmptyState icon="search" title="No recipients match your search" description="Check the spelling, or pay someone new with their IBAN." headingLevel={3}
          action={<Button variant="secondary" iconStart="user-plus" onClick={onAddNew}>Add a new recipient</Button>} />
      ) : (
        <Card variant="outlined" padding="none">
          <List aria-label="Saved recipients">
            {recipients.map((recipient) => (
              <ListItem key={recipient.id} title={recipient.name} description={`${recipient.bankName} · ${maskIban(recipient.iban)}`}
                leading={<Avatar name={recipient.name} decorative />} onClick={() => onChoose(recipient)} chevron />
            ))}
          </List>
        </Card>
      )}
    </div>
  );
}

function amountError(amountKurus: number | null, maxKurus: number, feeKurus: number): ReactNode | undefined {
  if (amountKurus === null) return "Enter the amount you want to send.";
  if (amountKurus < MIN_AMOUNT_KURUS) return <>The smallest amount you can send is <Money kurus={MIN_AMOUNT_KURUS} size="sm" />.</>;
  if (amountKurus > maxKurus) return <>This is more than you have. You can send up to <Money kurus={maxKurus} size="sm" />{feeKurus > 0 ? " after the fee." : "."}</>;
  return undefined;
}

function AmountStep({ recipient, account, amount, onAmountChange, description, onDescriptionChange, onChangeRecipient, onContinue }: {
  recipient: Recipient; account: Account; amount: number | null; onAmountChange: (amount: number | null) => void;
  description: string; onDescriptionChange: (description: string) => void; onChangeRecipient: () => void; onContinue: () => void;
}) {
  const [submitted, setSubmitted] = useState(false);
  const amountId = useId();
  const feeKurus = feeKurusFor(recipient);
  const maxKurus = Math.max(0, account.balanceKurus - feeKurus);
  const amountKurus = amount === null ? null : toKurus(amount);
  const error = submitted ? amountError(amountKurus, maxKurus, feeKurus) : undefined;
  const totalKurus = (amountKurus ?? 0) + feeKurus;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitted(true);
    if (amountError(amountKurus, maxKurus, feeKurus)) { document.getElementById(amountId)?.focus(); return; }
    onContinue();
  }

  return (
    <section style={styles.section} aria-labelledby={STEP_HEADING_ID}>
      <StepHeading>How much are you sending?</StepHeading>
      <Card variant="outlined" padding="none">
        <List aria-label="Recipient">
          <ListItem title={recipient.name} description={`${recipient.bankName} · ${maskIban(recipient.iban)}`} leading={<Avatar name={recipient.name} decorative />}
            trailing={<Button size="sm" variant="ghost" onClick={onChangeRecipient} aria-label={`Change recipient, currently ${recipient.name}`}>Change</Button>} />
        </List>
      </Card>
      <form noValidate onSubmit={handleSubmit} style={styles.section}>
        <div style={styles.group}>
          <AmountInput id={amountId} label="Amount" currency={CURRENCY} locale={LOCALE} value={amount} onValueChange={onAmountChange}
            min={toLira(MIN_AMOUNT_KURUS)} max={toLira(maxKurus)} hint={<>Available: <Money kurus={account.balanceKurus} size="sm" /></>} {...(error ? { error } : {})} />
          <TextField label="Description" optional hint="Shown to the recipient on their statement" maxLength={DESCRIPTION_MAX_LENGTH} autoComplete="off"
