        <Heading level={2} size="h3" id={STEP_HEADING_ID} tabIndex={-1}>Money sent</Heading>
        <Text tone="secondary">{recipient.name} gets <Money kurus={amountKurus} size="sm" /> {arrivalCopy(recipient).toLocaleLowerCase(LOCALE)}.</Text>
      </div>
